const COUNTRY_MAP = new Map<string, CountryData>();
const DIAL_MAP = new Map<string, CountryData>();
const CURRENCY_MAP = new Map<string, string>();

for (const c of ALL_COUNTRIES) {
  COUNTRY_MAP.set(c.code, c);
  if (!DIAL_MAP.has(c.dialCode)) DIAL_MAP.set(c.dialCode, c);
  if (c.currency) CURRENCY_MAP.set(c.code, c.currency);
}

export function getCountryByIso(code?: string): CountryData | undefined {
  if (!code) return undefined;
  return COUNTRY_MAP.get(code.trim().toUpperCase());
}

export function getCountryByDial(dialCode?: string): CountryData | undefined {
  if (!dialCode) return undefined;
  const digits = dialCode.replace(/[^\d]/g, '');
  if (!digits) return undefined;
  return DIAL_MAP.get('+' + digits);
}

export function getCurrencyByIso(code?: string): string {
  if (!code) return 'USD';
  return CURRENCY_MAP.get(code.trim().toUpperCase()) || 'USD';
}
